"""Source-backed A028 mode writers and generic name-tuple reader."""
import sys,json
from pathlib import Path
sys.dont_write_bytecode=True
p=Path(__file__).resolve().parents[2];sys.path.insert(0,str(p/'skoolkit-10.1'))
from skoolkit.traceutils import disassemble
from skoolkit.z80 import Assembler
m=bytes(0x5d80)+(p/'sherlock-analisi/block-10.bin').read_bytes();asm=Assembler()
regions=[(0xA028,0xA029,'data','Modo dei qualificatori nella tuple nome: completo0 / senza qualificatori nonzero'),(0xA37D,0xA419,'code','Composizione dell’azione: nome completo prima di parole e argomenti'),(0xA65D,0xA679,'code','Argomento nome completo e lettura della coda argomenti'),(0xA709,0xA751,'code','Nome letterale, soggetto, oggetto e altro referente: writer distinti'),(0xA793,0xA7BA,'code','Nome con copula: modo0 del soggetto e modo1 dell’oggetto'),(0xA7BA,0xA7D0,'code','Tuple nome e nome entità: due ingressi distinti'),(0xD1C6,0xD1DB,'code','Nome della locazione: reset del modo prima del formatter'),(0xD3D5,0xD448,'code','Formatter dei nomi: entità e tuple generica, salto dei qualificatori'),(0xD526,0xD55A,'code','Elenco dei contenuti: modo completo per ogni oggetto'),(0xD60B,0xD670,'code','Descrizione dei passaggi: ingresso diretto nel nome entità, conserva il modo')]
notes={0xA028:'Byte mutabile distinto dal canaleA027. Nonzero salta i due qualificatori nel formatterD405; il nome entitàD3E8 segue invece proprietà dell’entità. Non dedurre un0 globale dal payload.',0xA37E:'Scrive0 prima della composizione del modello. Ultimo writer naturale prima della lettura della cuoca: tick3399, giardiniere8, chiamanteA34B.',0xA65E:'Comando testo0: scrive0 prima di consumare la tuple nome passata come argomento. Non implica che sia un ID locazione: può puntare ai nomi di entità nelle risposte sulle informazioni.',0xA709:'Comando testo4: descrittore lessicale letterale. Non scriveA028; non unificarlo col comando0 solo perché la riscrittura usa lo stesso adapter nameArgument.',0xA721:'Nome del soggetto: modo0, anche se la parola è poi soppressa o il soggetto èHolmes.',0xA72E:'Nome dell’oggetto corrente: modo1 prima del nome. Il nome entità entra aD3E8 e non sopprime per questo i propri aggettivi.',0xA73D:'Altro referente: modo1, comeA72E ma leggeA035.',0xA798:'Soggetto con copula:0 daA797. Oggetto con copula:1 daA7B0. Variante argomentoA7B4: ID entità dal byte altoD, conservato inAF alternativo; il modo scritto resta1. La condizione del lettore è comunque nonzero.',0xD1D2:'Nome della locazione corrente:0 prima della tupleD405. I nomi usati soltanto da mappa/UI non sono questo writer.',0xD3E8:'Nome entità: non leggeA028. Qualificatori selezionati dai bit del record; non applicare qui il filtro generico delle locazioni.',0xD410:'LeggeA028 dopo articolo/proper-name setup: se nonzero saltaD416–D435 e stampa solo il sostantivo inD438. Vale per ogni tuple nome, non soltanto per i record delle stanze.',0xD536:'Ogni elemento effettivamente elencato imposta0. Nessun writer se la lista è vuota.',0xD658:'Ingresso direttoD3D5 del nome del passaggio: conservaA028. La presenza di un nome nella frase non basta a stabilire un nuovo modo.'}
fields={0xA028:[['0','nome completo','Il formatter generico considera i due qualificatori prima del sostantivo'],['nonzero','salta i qualificatori','Conserva articolo e sostantivo; 1,7,128 verificati contro il codice originale'],['Entità','ingressoD3E8','Non consulta questo byte: non cancellare gli aggettivi degli oggetti solo perché il modo è1'],['LOAD/UI','proprietà e purezza','OldLOAD assente restaunknown; i nomi consultati dalla mappa non modificano lo stato del gioco']]}
lines=['; Dossier offline: dati e codice distinti, riassellati contro il payload.'];count=total=0
for a,b,kind,label in regions:
 lines+=['',f'    ORG ${a:04X}',f'; {kind.upper()}: {label}'];at=a
 while at<b:
  if kind=='data':n=min(8,b-at);op='DEFB '+','.join(f'${v:02X}'for v in m[at:at+n])
  else:op,n=disassemble(m,at);count+=1
  assert at+n<=b,(hex(at),op);assert bytes(asm.assemble(op,at))==m[at:at+n]
  lines.append(f'    {op:<37} ; ${at:04X} {m[at:at+n].hex(" ")}'+(' | '+notes[at]if at in notes else''));at+=n;total+=n
root=p/'sherlock-js/results/name-qualifier-mode';root.mkdir(exist_ok=True);(root/'name-qualifier-mode.asm').write_text('\n'.join(lines)+'\n');(root/'listing-verification.json').write_text(json.dumps(dict(roundtrip_equal=True,instructions=count,bytes_roundtripped=total,regions=[dict(start=f'{a:04X}',end_exclusive=f'{b:04X}',kind=k,label=l,atlas_priority=143,**({'fields':fields[a]}if a in fields else{}))for a,b,k,l in regions]),indent=2)+'\n');print(count,total)
